package com.bank.jvm.kube;

import java.util.logging.Logger;

public class ContainerAwarenessProbe {
    private static final Logger log = Logger.getLogger(ContainerAwarenessProbe.class.getName());

    public static void main(String[] args) {
        log.info("Bank: National Bank of India — container-awareness probe");

        ContainerEnvReporter reporter = new ContainerEnvReporter();
        long heapMaxMb = reporter.reportHeapMax();
        int cpus = reporter.reportProcessors();

        // A heuristic check: on a big node without container support, heap would be huge.
        if (heapMaxMb > 8192) {
            log.severe(() -> "Heap max " + heapMaxMb + "MB looks like HOST sizing — "
                    + "container support may be OFF or JVM too old");
        } else {
            log.info(() -> "Heap max " + heapMaxMb + "MB looks container-sized — good");
        }

        K8sSizingAdvice advice = new K8sSizingAdvice();
        advice.print(log, 1024); // for a 1Gi pod
    }
}

// ─── Would be in K8sSizingAdvice.java in a real project ───
class K8sSizingAdvice {
    void print(Logger log, long podLimitMb) {
        long recommendedHeap = (long) (podLimitMb * 0.75);
        log.info(() -> "For a " + podLimitMb + "MB pod:");
        log.info(() -> "  resources.requests.memory == resources.limits.memory (Guaranteed QoS)");
        log.info(() -> "  -XX:MaxRAMPercentage=75.0  -> heap ~ " + recommendedHeap + "MB");
        log.info("  -XX:+ExitOnOutOfMemoryError -> clean restart on OOM");
        log.info("  -XX:+HeapDumpOnOutOfMemoryError -> capture evidence first");
    }
}
