package com.bank.jvm.kube;

import java.lang.management.ManagementFactory;
import java.util.logging.Logger;

class ContainerEnvReporter {
    private static final Logger log = Logger.getLogger(ContainerEnvReporter.class.getName());

    long reportHeapMax() {
        long maxMb = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getMax() / (1024 * 1024);
        log.info(() -> "Effective max heap = " + maxMb + "MB (should reflect cgroup limit)");
        return maxMb;
    }

    int reportProcessors() {
        // With container support, this reflects the CPU quota, not all host cores.
        int cpus = Runtime.getRuntime().availableProcessors();
        log.info(() -> "availableProcessors() = " + cpus + " (sizes thread pools / GC threads)");
        return cpus;
    }
}
